            float a_val3 = As[ty * SUB_TILE_SIZE + 3][k];

            float b_val0 = Bs[k][tx * SUB_TILE_SIZE];
            float b_val1 = Bs[k][tx * SUB_TILE_SIZE + 1];
            float b_val2 = Bs[k][tx * SUB_TILE_SIZE + 2];
            float b_val3 = Bs[k][tx * SUB_TILE_SIZE + 3];

