            c[2][1] += a_val2 * b_val1;
            c[2][2] += a_val2 * b_val2;
            c[2][3] += a_val2 * b_val3;

            c[3][0] += a_val3 * b_val0;
            c[3][1] += a_val3 * b_val1;
            c[3][2] += a_val3 * b_val2;
            c[3][3] += a_val3 * b_val3;
        }

