cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define SUB_TILE_SIZE 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Double buffered shared memory for tiles of A and B
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Starting position for the block
    int row_start = by * TILE_SIZE;
    int col_start = bx * TILE_SIZE;

    // Each thread computes an 8x8 block of C
    float c[SUB_TILE_SIZE][SUB_TILE_SIZE] = {{0.0f}};

    // Preload first tile
    int tile_idx = 0;

    // Load tile of A into shared memory (buffer 0)
    int A_row = row_start + ty * SUB_TILE_SIZE;
    int A_col = tile_idx * TILE_SIZE + tx * SUB_TILE_SIZE;

    // Load 8x8 tile of A using vectorized loads
    float4 A_val0, A_val1;
    if (A_row < N && A_col < N) {
        A_val0 = *reinterpret_cast<const float4*>(&A[A_row * N + A_col]);
        A_val1 = *reinterpret_cast<const float4*>(&A[A_row * N + A_col + 4]);

        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE] = A_val0.x;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 1] = A_val0.y;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 2] = A_val0.z;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 3] = A_val0.w;

        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 4] = A_val1.x;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 5] = A_val1.y;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 6] = A_val1.z;
        As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 7] = A_val1.w;
    } else {
        for (int i = 0; i < SUB_TILE_SIZE; i++) {
            As[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + i] = 0.0f;
        }
    }

    // Load tile of B into shared memory (buffer 0)
    int B_row = tile_idx * TILE_SIZE + ty * SUB_TILE_SIZE;
    int B_col = col_start + tx * SUB_TILE_SIZE;

    // Load 8x8 tile of B using vectorized loads
    float4 B_val0, B_val1;
    if (B_row < N && B_col < N) {
        B_val0 = *reinterpret_cast<const float4*>(&B[B_row * N + B_col]);
        B_val1 = *reinterpret_cast<const float4*>(&B[B_row * N + B_col + 4]);

        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE] = B_val0.x;
        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 1] = B_val0.y;
        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 2] = B_val0.z;
        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 3] = B_val0.w;

        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 4] = B_val1.x;
        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 5] = B_val1.y;
        Bs[0][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 6] = B_val1.z;
