                As[next_tile_idx][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE] = next_A_val0.x;
                As[next_tile_idx][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 1] = next_A_val0.y;
                As[next_tile_idx][ty * SUB_TILE_SIZE][tx * SUB_TILE_SIZE + 2] = next_A_val0.z;
