    for (int i = 0; i < SUB_TILE_SIZE; i++) {
        int A_row = row_start + ty * SUB_TILE_SIZE + i;
        for (int j = 0; j < SUB_TILE_SIZE; j++) {
            int A_col = tile_idx * TILE_SIZE + tx * SUB_TILE_SIZE + j;
            if (A_row < N && A_col < N) {
                As[0][ty * SUB_TILE_SIZE + i][tx * SUB_TILE_SIZE + j] = A[A_row * N + A_col];
            } else {
                As[0][ty * SUB_TILE_SIZE + i][tx * SUB_TILE_SIZE + j] = 0.0f;
            }
        }
    }

