    // Loop over tiles with double buffering
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t++) {
        int next_tile = t + 1;
        int next_tile_idx = (tile_idx + 1) % 2;

        // Preload next tile while computing current tile
        if (next_tile < num_tiles) {
