                    } else {
                        As[next_tile_idx][ty * SUB_TILE_SIZE + i][tx * SUB_TILE_SIZE + j] = 0.0f;
                    }
                }
            }

            // Load next tile of B into shared memory
            for (int i = 0; i < SUB_TILE_SIZE; i++) {
                int next_B_row = next_tile * TILE_SIZE + ty * SUB_TILE_SIZE + i;
                for (int j = 0; j < SUB_TILE_SIZE; j++) {
                    int next_B_col = col_start + tx * SUB_TILE_SIZE + j;
                    if (next_B_row < N && next_B_col < N) {
